sys_script_client.script:
function onLoad() {
    if (g_form.getValue('hr_service') != "6a2b1ada2f4f2c904cbeb1e72799b6ae") { //If not incident reporting, return
        return;
    }

    // Test method to add info text to type of occurrence field
    // g_form.showFieldMsg('inc_type_occ', 'Test info text');

    if (g_user.userID != g_form.getValue('manager_name')) { //If user is not the manager of the case, return
        return;
    }
    g_form.setSectionDisplay('fulfillment_instructions', false);
    g_form.setSectionDisplay('comments_andworknotes', false);
    g_form.setSectionDisplay('subcases_andtasks', false);
    g_form.setSectionDisplay('case_information', false);
    g_form.setSectionDisplay('manager', false);
    g_form.setSectionDisplay('whsc', false);
    g_form.setSectionDisplay('ohs', false);

    //Show again the tabs starting with the manager, so that it will be shown by default
    g_form.setSectionDisplay('case_information', true);
    g_form.setSectionDisplay('manager', true);
    g_form.setSectionDisplay('fulfillment_instructions', true);
    g_form.setSectionDisplay('comments_andworknotes', true);
    g_form.setSectionDisplay('subcases_andtasks', true);
    g_form.setSectionDisplay('whsc', true);
    if (g_scratchpad.hasOHSGroups == false && g_scratchpad.isDeveloper == false && g_scratchpad.hasOHSAdmin == false) {
        g_form.setSectionDisplay('ohs', false);
    } else {
        g_form.setSectionDisplay('ohs', true);
    }
}
